size_t i, k;
size_t count;
adcs_quat_t q_full;
adcs_quat_t q_use;
adcs_mat3_t dcm;
double worst_full, worst_use, residual;
size_t worst_idx;
const adcs_vec3_t *body;
const adcs_vec3_t *inertial;
const double *weights;
adcs_vec3_t body_red[4];
adcs_vec3_t rotated;
adcs_vec3_t diff;
adcs_status_t st;

if ((qr_state.mode == QR_FAULT) && (qr_input.enable != 0)) {
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    return;
}

if (qr_input.enable == 0) {
    qr_state.mode = QR_OFF;
    qr_state.good = 0U;
    qr_output.mode = QR_OFF;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    qr_output.used_count = 0U;
    qr_output.rejected_outlier = 0;
    return;
}

body = qr_input.body;
inertial = qr_input.inertial;
weights = qr_input.weights;
count = qr_input.count;

if ((body == NULL) || (inertial == NULL) || (weights == NULL) ||
    (count < 2U) || (count > 4U) ||
    (!isfinite(qr_config.residual_limit_rad)) ||
    (qr_config.residual_limit_rad < 0.0) ||
    (qr_config.residual_limit_rad > ADCS_PI) ||
    (qr_config.required_good < 1U) || (qr_config.required_good > 20U) ||
    ((qr_config.allow_outlier_reject != 0) && (qr_config.allow_outlier_reject != 1))) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    qr_output.used_count = count;
    qr_output.rejected_outlier = 0;
    return;
}

for (i = 0; i < count; i++) {
    if ((!adcs_is_finite_vec3(&body[i])) || (!adcs_is_finite_vec3(&inertial[i])) ||
        (!isfinite(weights[i])) || (weights[i] <= 0.0)) {
        qr_state.mode = QR_FAULT;
        qr_state.good = 0U;
        qr_output.mode = QR_FAULT;
        qr_output.good = 0U;
        qr_output.worst_residual_rad = 0.0;
        qr_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        qr_output.used_count = count;
        qr_output.rejected_outlier = 0;
        return;
    }
}

st = adcs_quest(body, inertial, weights, count, &q_full);
if (st != ADCS_OK) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    qr_output.used_count = count;
    qr_output.rejected_outlier = 0;
    return;
}

dcm = adcs_quat_to_dcm_bi(&q_full);
worst_full = -1.0;
worst_idx = 0U;
for (i = 0; i < count; i++) {
    rotated = adcs_mat3_mul_vec(&dcm, &inertial[i]);
    diff = adcs_vec3_sub(&rotated, &body[i]);
    residual = adcs_vec3_norm(&diff);
    if (residual > worst_full) {
        worst_full = residual;
        worst_idx = i;
    }
}

q_use = q_full;
worst_use = worst_full;
qr_output.used_count = count;
qr_output.rejected_outlier = 0;

if ((worst_full > qr_config.residual_limit_rad) &&
    (qr_config.allow_outlier_reject != 0) && (count > 2U)) {
    adcs_vec3_t in_red[4];
    double w_red[4];
    adcs_mat3_t dcm_red;
    double worst_red = -1.0;
    adcs_status_t st2;

    k = 0U;
    for (i = 0; i < count; i++) {
        if (i == worst_idx) {
            continue;
        }
        body_red[k] = body[i];
        in_red[k] = inertial[i];
        w_red[k] = weights[i];
        k++;
    }

    st2 = adcs_quest(body_red, in_red, w_red, count - 1U, &q_use);
    if (st2 == ADCS_OK) {
        dcm_red = adcs_quat_to_dcm_bi(&q_use);
        for (i = 0; i < count - 1U; i++) {
            rotated = adcs_mat3_mul_vec(&dcm_red, &in_red[i]);
            diff = adcs_vec3_sub(&rotated, &body_red[i]);
            residual = adcs_vec3_norm(&diff);
            if (residual > worst_red) {
                worst_red = residual;
            }
        }
        if (worst_red <= qr_config.residual_limit_rad) {
            worst_use = worst_red;
            qr_output.used_count = count - 1U;
            qr_output.rejected_outlier = 1;
        } else {
            q_use = q_full;
            worst_use = worst_full;
            qr_output.used_count = count;
            qr_output.rejected_outlier = 0;
        }
    } else {
        q_use = q_full;
        worst_use = worst_full;
        qr_output.used_count = count;
        qr_output.rejected_outlier = 0;
    }
}

qr_output.worst_residual_rad = worst_use;
qr_output.q_bi = q_use;

if (worst_use <= qr_config.residual_limit_rad) {
    if (qr_state.good < 0xFFFFFFFFU) {
        qr_state.good += 1U;
    }
    if (qr_state.good >= qr_config.required_good) {
        qr_state.mode = QR_READY;
    } else {
        qr_state.mode = QR_MONITOR;
    }
} else {
    qr_state.good = 0U;
    qr_state.mode = QR_MONITOR;
}
qr_output.good = qr_state.good;
qr_output.mode = qr_state.mode;

