size_t i, k;
int valid_input = 1;
int enable = 0;
double limit;
unint32 required_good;
int allow_reject;

if (qr_state.mode == QR_FAULT) {
    if (qr_input.enable != 0) {
        qr_output.mode = QR_FAULT;
        qr_output.good = qr_state.good;
        qr_output.worst_residual_rad = qr_config.residual_limit_rad;
        qr_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        qr_output.used_count = 0U;
        qr_output.rejected_outlier = 0;
        return;
    }
}

if ((qr_input.body == NULL) || (qr_input.inertial == NULL) || (qr_input.weights == NULL)) {
    valid_input = 0;
}
if ((qr_input.count < 2U) || (qr_input.count > 4U)) {
    valid_input = 0;
}
if ((qr_config.residual_limit_rad < 0.0) ||
    (qr_config.residual_limit_rad > ADCS_PI) ||
    (!isfinite(qr_config.residual_limit_rad))) {
    valid_input = 0;
}
if ((qr_config.required_good < 1U) || (qr_config.required_good > 20U)) {
    valid_input = 0;
}
if ((qr_config.allow_outlier_reject != 0) && (qr_config.allow_outlier_reject != 1)) {
    valid_input = 0;
}
if ((qr_input.enable != 0) && (qr_input.enable != 1)) {
    valid_input = 0;
}
if (valid_input) {
    for (i = 0; i < qr_input.count; i++) {
        if ((!adcs_is_finite_vec3(&qr_input.body[i])) ||
            (!adcs_is_finite_vec3(&qr_input.inertial[i])) ||
            (!isfinite(qr_input.weights[i])) ||
            (qr_input.weights[i] <= 0.0)) {
            valid_input = 0;
            break;
        }
    }
}

if (!valid_input) {
    qr_state.mode = QR_FAULT;
    qr_state.good = 0U;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = qr_config.residual_limit_rad;
    qr_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    qr_output.used_count = 0U;
    qr_output.rejected_outlier = 0;
    return;
}

enable = qr_input.enable;
limit = qr_config.residual_limit_rad;
required_good = qr_config.required_good;
allow_reject = qr_config.allow_outlier_reject;

if (enable == 0) {
    qr_state.mode = QR_OFF;
    qr_state.good = 0U;
    qr_output.mode = QR_OFF;
    qr_output.good = 0U;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    qr_output.used_count = qr_input.count;
    qr_output.rejected_outlier = 0;
    return;
}

{
    adcs_quat_t q_full;
    adcs_status_t st_full;
    double worst_full = -1.0;
    size_t worst_idx_full = 0U;

    st_full = adcs_quest(qr_input.body, qr_input.inertial, qr_input.weights,
                         qr_input.count, &q_full);
    if (st_full != ADCS_OK) {
        qr_state.mode = QR_FAULT;
        qr_state.good = 0U;
        qr_output.mode = QR_FAULT;
        qr_output.good = 0U;
        qr_output.worst_residual_rad = limit;
        qr_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        qr_output.used_count = qr_input.count;
        qr_output.rejected_outlier = 0;
        return;
    }

    {
        adcs_mat3_t c_full = adcs_quat_to_dcm_bi(&q_full);
        for (i = 0; i < qr_input.count; i++) {
            adcs_vec3_t body_n, pred, err;
            double r;
            (void)adcs_vec3_normalize(&qr_input.body[i], ADCS_EPS_NORM, &body_n);
            pred = adcs_mat3_mul_vec(&c_full, &qr_input.inertial[i]);
            (void)adcs_vec3_normalize(&pred, ADCS_EPS_NORM, &pred);
            err = adcs_vec3_sub(&body_n, &pred);
            r = adcs_vec3_norm(&err);
            if (r > worst_full) {
                worst_full = r;
                worst_idx_full = i;
            }
        }
    }

    {
        adcs_quat_t q_used;
        adcs_vec3_t used_body[4];
        adcs_vec3_t used_inertial[4];
        double used_weights[4];
        size_t used_count;
        int rejected = 0;
        double worst_used = worst_full;

        q_used = q_full;
        used_count = qr_input.count;

        if ((worst_full > limit) && (allow_reject != 0) && (qr_input.count > 2U)) {
            size_t m = 0U;
            for (i = 0; i < qr_input.count; i++) {
                if (i == worst_idx_full) {
                    continue;
